@CrossOrigin
@RestController
@RequestMapping("/AgentQuery")
public class AgentQueryRestController extends BaseSpringRestController {
	
	public AgentQueryRestController( AgentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Agent using a UUID
     * @param		UUID agentId
     * @return		Agent
     */    
    @GetMapping("/load")
    public Agent load( @RequestParam(required=true) UUID agentId ) {
    	Agent entity = null;

    	try {  
    		entity = service.getAgent( new AgentFetchOneSummary( agentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Agent using Id " + agentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Agent business objects
     * @return		Set<Agent>
     */
    @GetMapping("/")
    public List<Agent> loadAll() {                
    	List<Agent> agentList = null;
        
    	try {
            // load the Agent
            agentList = service.getAllAgent();
            
            if ( agentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Agents" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Agents ", exc );
        	return null;
        }

        return agentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Agent agent = null;
    protected AgentService service = null;
    private static final Logger LOGGER = Logger.getLogger(AgentQueryRestController.class.getName());
    
}
